/**
 * tools/bundle.js — concatenate src/*.gs into one file.
 *
 * Apps Script loads every .gs file into a single shared scope, so the bundle is
 * a plain concatenation. It exists for people installing without a terminal:
 * one paste instead of eleven.
 *
 * Order matters only for the top-level `var` assignments (DEFAULT_CONFIG, the
 * Store IIFE). Function declarations hoist, so everything else is free.
 */
const fs = require('fs');
const path = require('path');

const ORDER = [
  'Config.gs', 'Store.gs', 'Workflow.gs', 'Transcript.gs', 'Prompt.gs',
  'Classifier.gs', 'Labels.gs', 'Scanner.gs', 'Digest.gs', 'Main.gs', 'Tests.gs'
];

const SRC = path.join(__dirname, '..', 'src');
const OUT = path.join(__dirname, '..', 'dist', 'Bundle.gs');

const onDisk = fs.readdirSync(SRC).filter((f) => f.endsWith('.gs')).sort();
const missing = onDisk.filter((f) => !ORDER.includes(f));
if (missing.length) {
  console.error('These source files are not listed in ORDER: ' + missing.join(', '));
  process.exit(1);
}

const rule = '// ' + '='.repeat(74);
const parts = [
  rule,
  '// Gmail Workflow Automation — single-file build',
  '//',
  '// Generated by tools/bundle.js. Do not edit this file; edit src/ and rebuild',
  '// with `npm run bundle`. Paste the whole thing into one Apps Script file.',
  '//',
  '// You still need src/appsscript.json in the project manifest — it declares',
  '// the permissions, and it cannot live inside this file.',
  rule,
  ''
];

for (const name of ORDER) {
  parts.push('', rule, '// ' + name, rule, '', fs.readFileSync(path.join(SRC, name), 'utf8').trim(), '');
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, parts.join('\n') + '\n');

const bytes = fs.statSync(OUT).size;
const lines = fs.readFileSync(OUT, 'utf8').split('\n').length;
console.log(`dist/Bundle.gs — ${ORDER.length} files, ${lines} lines, ${(bytes / 1024).toFixed(1)} KB`);
